steps.codeExample:
e := echo.New()

e.POST("/orders", func(c echo.Context) error {
    var req CreateOrderReq
    if err := c.Bind(&req); err != nil {
        return c.JSON(http.StatusBadRequest, map[string]string{"error": err.Error()})
    }
    return c.JSON(http.StatusCreated, req)
})

